(() => {
  const map = window.__big.map;
  window.__bconv = { done: false, round: 0, charsDone: 0, added: 0, rounds: [], seeded: {}, started: Date.now(), conc: 2 };
  const S = window.__bconv;
  (async () => {
    const sleep = ms => new Promise(r => setTimeout(r, ms));
    const post = async (ch) => {
      for (let a = 0; a < 4; a++) {
        try {
          const r = await fetch('/draco-ms/mms/template/property/value/search', { method: 'POST', headers: { 'Content-Type': 'application/json' }, credentials: 'include', body: JSON.stringify({ cat_id: 5908, pid: 5, template_pid: 642609, page_num: 1, page_size: 1000, value: ch }) });
          const j = await r.json();
          if (j && j.success) return Array.isArray(j.result) ? j.result : [];
          if (j && (j.error_code === 55555 || j.error_code === 40002)) { S.throttled = (S.throttled || 0) + 1; await sleep(1500 * (a + 1)); continue; }
          return [];
        } catch (e) { await sleep(800 * (a + 1)); }
      }
      return [];
    };
    for (let round = 1; round <= 8; round++) {
      const chars = {};
      for (const k in map) { const s = String(map[k] || ''); for (const ch of s) { if (/[\u4e00-\u9fa5]/.test(ch)) chars[ch] = 1; } }
      const seeds = Object.keys(chars).filter(c => !S.seeded[c]);
      S.charsKnown = Object.keys(chars).length;
      if (!seeds.length) { S.rounds.push({ round: round, seeds: 0, added: 0, note: '字集已收敛' }); break; }
      let added = 0, i = 0;
      const worker = async () => {
        while (i < seeds.length) {
          const c = seeds[i++];
          S.seeded[c] = 1;
          const arr = await post(c);
          for (const x of arr) { if (!(x.vid in map)) { map[x.vid] = x.value; added++; } }
          S.charsDone++;
          await sleep(110);
        }
      };
      await Promise.all(Array.from({ length: S.conc }, worker));
      S.round = round;
      S.added += added;
      S.rounds.push({ round: round, seeds: seeds.length, added: added, total: Object.keys(map).length });
      if (added === 0) break;
    }
    S.done = true; S.finishedAt = Date.now();
  })();
  return JSON.stringify({ msg: 'brand convergence job started', charsKnown: Object.keys((() => { const c = {}; for (const k in map) { const s = String(map[k] || ''); for (const ch of s) if (/[\u4e00-\u9fa5]/.test(ch)) c[ch] = 1; } return c; })()).length, currentBrands: Object.keys(map).length });
})()
